-- 0047_official_forms_drafts.sql
-- The official ServiceOntario forms (SR-LV-006, SR-LV-012, ON00453, 013-0169, 013-1155) as templates of Admin > Settings >
-- Forms (0042), each with a draft mapping to check (docs/changes/2026-10-16-supply-manual-rentals-signing.md, section 5). The
-- forms-fetch workflow resolved each dataset page of the Central Forms Repository to its English PDF, stored it in the
-- private documents bucket and recorded its fields (docs/forms/official-forms.json). Nothing changes for owners: every
-- template is unchecked, so owners keep the data sheet until an Admin presses "Checked: use for owners".
--
-- The publisher's PDFs are encrypted with an empty password and allow form filling; pdf-lib cannot open an encrypted
-- file, so the stored template is the same form opened (qpdf) with its XFA part removed (the AcroForm fields are used).
-- ON00453 has no AcroForm field at all (an Adobe dynamic form): its template is the form laid out by pdf.js as a plain
-- PDF, and its fields are boxes where the values are printed (kind 'overlay', a coordinates-based placement).

-- A template version from the fetched form. It becomes the current version unless an Admin already checked the current
-- one (then it waits beside it). A field the current version already maps keeps that mapping (as an upload does).
create or replace function app.official_form_draft(p_code text, p_title text, p_kind text, p_file_key text, p_sha256 text, p_pages integer,
                                                   p_file_name text, p_fields jsonb, p_map jsonb, p_notes text) returns uuid
language plpgsql security definer set search_path = public, app as $$
declare
  cur pdf_templates;
  v_id uuid;
  v_map jsonb := p_map;
  r record;
begin
  select id into v_id from pdf_templates where form_code = p_code and sha256 = p_sha256;
  if v_id is not null then return v_id; end if;
  select * into cur from pdf_templates where form_code = p_code and is_current for update;
  if cur.id is not null and not cur.verified then
    for r in select key, value from jsonb_each(cur.field_map) loop
      if exists (select 1 from jsonb_array_elements(p_fields) f where f ->> 'name' = r.key) then v_map := v_map || jsonb_build_object(r.key, r.value); end if;
    end loop;
    update pdf_templates set is_current = false where id = cur.id;
  end if;
  insert into pdf_templates (form_code, version, title, kind, file_key, sha256, page_count, field_map, verified, is_current, notes, field_names, file_name,
                             mapped_at)
  values (p_code, 'official-' || to_char(now() at time zone 'America/Toronto', 'YYYYMMDD') || '-' || ((select count(*) from pdf_templates x where x.form_code = p_code) + 1),
          p_title, p_kind, p_file_key, p_sha256, p_pages, v_map, false, cur.id is null or not cur.verified, p_notes, p_fields, p_file_name, now())
  returning id into v_id;
  return v_id;
end $$;
revoke all on function app.official_form_draft(text, text, text, text, text, integer, text, jsonb, jsonb, text) from public, anon, authenticated;
grant execute on function app.official_form_draft(text, text, text, text, text, integer, text, jsonb, jsonb, text) to service_role;

-- Three more sources for the drafts: 'always' (a box every copy of the form ticks, for example the Passenger class of
-- SR-LV-006), 'corporation.rin_missing' (the corporation has no Registrant Identification Number yet: the RIN form's
-- "New") and 'owner.unit' (the unit or apartment number without its word, "Unit 1204" becomes "1204", for the
-- six-character unit boxes). The context of 0022 is wrapped; everything else it returns is unchanged.
alter function app.registry_context(uuid) rename to registry_context_0022;
create or replace function app.registry_context(p_vehicle uuid) returns jsonb
language sql stable security definer set search_path = public, app as $$
  select c || jsonb_build_object('always', true,
              'corporation', coalesce(c -> 'corporation', '{}'::jsonb) || jsonb_build_object('rin_missing', nullif(btrim(coalesce(c #>> '{corporation,rin}', '')), '') is null),
              'owner', coalesce(c -> 'owner', '{}'::jsonb) || jsonb_build_object('unit',
                nullif(btrim(regexp_replace(coalesce(c #>> '{owner,address_line2}', ''), '^\s*(unit|apt\.?|apartment|suite|ste\.?|no\.?|#)\s*', '', 'i')), '')))
    from app.registry_context_0022(p_vehicle) c
$$;
revoke all on function app.registry_context(uuid) from public, anon, authenticated;
grant execute on function app.registry_context(uuid) to service_role;

alter function app.registry_sources() rename to registry_sources_0042;
create or replace function app.registry_sources() returns jsonb
language sql immutable as $$
  select app.registry_sources_0042() || jsonb_build_array(
    jsonb_build_object('path', 'owner.unit', 'label', 'Owner: unit or apartment number only', 'section', 'Owner'),
    jsonb_build_object('path', 'corporation.rin_missing', 'label', 'Corporation has no RIN yet (yes or no)', 'section', 'Corporation'),
    jsonb_build_object('path', 'always', 'label', 'Always (a box every copy of the form ticks)', 'section', 'Other'))
$$;
grant execute on function app.registry_sources() to service_role, authenticated;

-- The transforms Admin > Settings > Forms offers, with the registry's own date style (YYYY/MM/DD on SR-LV-006 and
-- SR-LV-012). The read of 0042 is wrapped; app.apply_transform already reads any date:<pattern>.
alter function app.form_templates(uuid) rename to form_templates_0042;
create or replace function app.form_templates(p_by uuid) returns jsonb
language sql stable security definer set search_path = public, app as $$
  select r || jsonb_build_object('transforms', (r -> 'transforms') || '["date:YYYY/MM/DD"]'::jsonb)
    from app.form_templates_0042(p_by) r
$$;
revoke all on function app.form_templates(uuid) from public, anon, authenticated;
grant execute on function app.form_templates(uuid) to service_role;

